/* =========================================================
   CSDL QUAN LY TIN CHI
   Chay tren SQL Server. Neu DB da ton tai thi drop truoc.
   ========================================================= */

IF DB_ID('QuanLyTinChi') IS NOT NULL
BEGIN
    ALTER DATABASE QuanLyTinChi SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE QuanLyTinChi;
END
GO

CREATE DATABASE QuanLyTinChi;
GO

USE QuanLyTinChi;
GO

/* ---------- 1. HOC_KY ---------- */
CREATE TABLE HOC_KY (
    MaHK        VARCHAR(20)     NOT NULL PRIMARY KEY,
    TenHK       NVARCHAR(100)   NULL,
    NamHoc      NVARCHAR(20)    NULL,
    NgayBatDau  DATE            NULL          -- LichHocPanel.java can cot nay
);
GO

/* ---------- 2. SINH_VIEN ---------- */
CREATE TABLE SINH_VIEN (
    MaSV                VARCHAR(20)     NOT NULL PRIMARY KEY,
    HoTen               NVARCHAR(100)   NULL,
    GioiTinh            NVARCHAR(10)    NULL,
    NgaySinh            DATE            NULL,
    SoDienThoai         NVARCHAR(20)    NULL,
    Email               NVARCHAR(100)   NULL,
    TrangThaiHocTap     NVARCHAR(50)    NULL,
    DatChuanNgoaiNgu    BIT             NOT NULL DEFAULT 0,
    MaCTDT              NVARCHAR(20)    NULL,
    MaLop               NVARCHAR(20)    NULL
);
GO

/* ---------- 3. GIANG_VIEN ---------- */
CREATE TABLE GIANG_VIEN (
    MaGV            VARCHAR(20)     NOT NULL PRIMARY KEY,
    HoTen           NVARCHAR(100)   NULL,
    GioiTinh        NVARCHAR(10)    NULL,
    HocVi           NVARCHAR(50)    NULL,
    SoDienThoai     NVARCHAR(20)    NULL,
    Email           NVARCHAR(100)   NULL,
    MaKhoa          NVARCHAR(50)    NULL
);
GO

/* ---------- 4. MON_HOC ---------- */
CREATE TABLE MON_HOC (
    MaMon       VARCHAR(20)     NOT NULL PRIMARY KEY,
    TenMon      NVARCHAR(100)   NULL,
    SoTinChi    INT             NULL CHECK (SoTinChi > 0)
);
GO

/* ---------- 5. MON_TIEN_QUYET ---------- */
CREATE TABLE MON_TIEN_QUYET (
    MaMon       VARCHAR(20) NOT NULL,
    MaMonTQ     VARCHAR(20) NOT NULL,
    CONSTRAINT PK_MonTienQuyet PRIMARY KEY (MaMon, MaMonTQ),
    CONSTRAINT FK_MTQ_Mon    FOREIGN KEY (MaMon)   REFERENCES MON_HOC(MaMon),
    CONSTRAINT FK_MTQ_MonTQ  FOREIGN KEY (MaMonTQ) REFERENCES MON_HOC(MaMon)
);
GO

/* ---------- 6. LOP_HOC_PHAN ---------- */
CREATE TABLE LOP_HOC_PHAN (
    MaLHP       VARCHAR(20)     NOT NULL PRIMARY KEY,
    MaMon       VARCHAR(20)     NULL,
    MaHK        VARCHAR(20)     NULL,
    Thu         NVARCHAR(20)    NULL,
    TietHoc     NVARCHAR(20)    NULL,
    PhongHoc    NVARCHAR(20)    NULL,
    SucChua     INT             NULL CHECK (SucChua >= 0),
    MaGV        VARCHAR(20)     NULL,        -- DangKyPanel.java JOIN qua cot nay
    CONSTRAINT FK_LHP_Mon FOREIGN KEY (MaMon) REFERENCES MON_HOC(MaMon),
    CONSTRAINT FK_LHP_HK  FOREIGN KEY (MaHK)  REFERENCES HOC_KY(MaHK),
    CONSTRAINT FK_LHP_GV  FOREIGN KEY (MaGV)  REFERENCES GIANG_VIEN(MaGV)
);
GO

/* ---------- 7. KET_QUA_DANG_KY ---------- */
CREATE TABLE KET_QUA_DANG_KY (
    MaSV            VARCHAR(20)     NOT NULL,
    MaLHP           VARCHAR(20)     NOT NULL,
    TrangThai       NVARCHAR(50)    NOT NULL DEFAULT N'Chưa có điểm',
    DiemChuyenCan   FLOAT           NULL,         -- DiemPanel.java can cot nay (diem thanh phan)
    DiemGiuaKy      FLOAT           NULL,         -- DiemPanel.java can cot nay (diem thanh phan)
    DiemCuoiKy      FLOAT           NULL,         -- DiemPanel.java can cot nay (diem thanh phan)
    DiemTongKet     FLOAT           NULL,         -- = DiemChuyenCan*10% + DiemGiuaKy*30% + DiemCuoiKy*60%
    CONSTRAINT PK_KetQuaDangKy PRIMARY KEY (MaSV, MaLHP),
    CONSTRAINT FK_KQDK_SV  FOREIGN KEY (MaSV)  REFERENCES SINH_VIEN(MaSV),
    CONSTRAINT FK_KQDK_LHP FOREIGN KEY (MaLHP) REFERENCES LOP_HOC_PHAN(MaLHP)
);
GO

/* Trigger: Ràng buộc một sinh viên không thể đăng ký nhiều môn học trong cùng một buổi (Sáng/Chiều) của một ngày */
CREATE TRIGGER TR_Check_TrungBuoiHoc
ON KET_QUA_DANG_KY
AFTER INSERT, UPDATE
AS
BEGIN
    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN LOP_HOC_PHAN l1 ON i.MaLHP = l1.MaLHP
        JOIN KET_QUA_DANG_KY k ON k.MaSV = i.MaSV
        JOIN LOP_HOC_PHAN l2 ON k.MaLHP = l2.MaLHP
        WHERE i.MaLHP <> k.MaLHP
          AND l1.MaHK = l2.MaHK
          AND l1.Thu = l2.Thu
          AND (CASE WHEN CAST(SUBSTRING(l1.TietHoc, 1, CHARINDEX('-', l1.TietHoc)-1) AS INT) <= 6 THEN 1 ELSE 2 END) = 
              (CASE WHEN CAST(SUBSTRING(l2.TietHoc, 1, CHARINDEX('-', l2.TietHoc)-1) AS INT) <= 6 THEN 1 ELSE 2 END)
    )
    BEGIN
        RAISERROR (N'Lỗi: Sinh viên không thể đăng ký nhiều môn học trong cùng một buổi (Sáng/Chiều) của một ngày!', 16, 1);
        ROLLBACK TRANSACTION;
    END
END
GO

/* ---------- 8. CONG_NO_HOC_PHI ---------- */
CREATE TABLE CONG_NO_HOC_PHI (
    MaPhieu             VARCHAR(20)     NOT NULL PRIMARY KEY,
    MaSV                VARCHAR(20)     NULL,
    MaHK                VARCHAR(20)     NULL,
    TongTienPhaiDong    DECIMAL(18,2)   NULL,
    SoTienDaDong        DECIMAL(18,2)   NOT NULL DEFAULT 0,
    TrangThai           NVARCHAR(50)    NOT NULL DEFAULT N'Chưa đóng',
    CONSTRAINT FK_CNHP_SV FOREIGN KEY (MaSV) REFERENCES SINH_VIEN(MaSV),
    CONSTRAINT FK_CNHP_HK FOREIGN KEY (MaHK) REFERENCES HOC_KY(MaHK)
);
GO

